PROGRAM IsPrime(INPUT, OUTPUT);
VAR
  n, i: INTEGER;
  prime: BOOLEAN;
BEGIN
  READLN(n);
  prime := n > 1;
  i := 2;
  WHILE (i * i <= n) AND prime DO
  BEGIN
    IF n MOD i = 0 THEN
      prime := FALSE;
    i := i + 1
  END;
  IF prime THEN
    WRITELN(n, ' is prime')
  ELSE
    WRITELN(n, ' is not prime')
END.
